//! The append-only registry of unit-code identities.

use crate::{rec20_revision::Rec20Revision, unit_code_entry::UnitCodeEntry, unit_code_id::UnitCodeId, unit_code_token::UnitCodeToken};
use cefact_units::UnitCode;
use std::{collections::HashMap, sync::LazyLock};
use thiserror::Error;

/// The committed identity assignment, compiled into the binary.
///
/// The snapshot is the release's promise: it is regenerated by appending, never
/// by reassigning, so an identifier a previous release wrote into a row keeps
/// naming the same code.
const SNAPSHOT: &str = include_str!("../data/unit-code-ids.tsv");

/// Column separator of the committed snapshot.
const FIELD_SEPARATOR: char = '\t';

/// Number of columns each snapshot registration carries.
const FIELD_COUNT: usize = 4;

/// The parsed registry, built once per process.
static REGISTRY: LazyLock<Result<UnitCodeRegistry, UnitCodeSnapshotMalformed>> = LazyLock::new(|| UnitCodeRegistry::parse(SNAPSHOT));

/// Return the process-wide unit-code registry.
///
/// # Errors
///
/// Returns [`UnitCodeSnapshotMalformed`] when the committed snapshot does not
/// parse. The generation test rejects such a snapshot before it can be
/// committed, so this failure describes a corrupted build rather than a
/// condition a caller can provoke.
pub fn registry() -> Result<&'static UnitCodeRegistry, UnitCodeSnapshotMalformed> {
    REGISTRY.as_ref().map_err(|error| *error)
}

/// Every unit code the catalog has ever assigned an identity to.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct UnitCodeRegistry {
    /// Registrations in the order the snapshot lists them.
    entries: Vec<UnitCodeEntry>,
    /// Position of each registration by its identity.
    by_id: HashMap<UnitCodeId, usize>,
    /// Position of each registration by its token.
    by_token: HashMap<UnitCodeToken, usize>,
}

impl UnitCodeRegistry {
    /// Read a registry from the committed snapshot format.
    ///
    /// # Errors
    ///
    /// Returns [`UnitCodeSnapshotMalformed`] when a line does not carry four
    /// fields, when a field does not parse, or when an identity or token
    /// repeats.
    pub fn parse(snapshot: &'static str) -> Result<UnitCodeRegistry, UnitCodeSnapshotMalformed> {
        let mut registry = UnitCodeRegistry {
            entries: Vec::new(),
            by_id: HashMap::new(),
            by_token: HashMap::new(),
        };
        for (offset, line) in snapshot.lines().enumerate() {
            let number = offset + 1;
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            registry.push(parse_entry(line, number)?, number)?;
        }
        Ok(registry)
    }

    /// Add one registration, rejecting a repeated identity or token.
    fn push(&mut self, entry: UnitCodeEntry, line: usize) -> Result<(), UnitCodeSnapshotMalformed> {
        let position = self.entries.len();
        if self.by_id.insert(entry.id(), position).is_some() {
            return Err(UnitCodeSnapshotMalformed::RepeatedIdentity { line });
        }
        if self.by_token.insert(entry.token(), position).is_some() {
            return Err(UnitCodeSnapshotMalformed::RepeatedToken { line });
        }
        self.entries.push(entry);
        Ok(())
    }

    /// Return every registration in the order the snapshot lists them.
    pub fn entries(&self) -> &[UnitCodeEntry] {
        &self.entries
    }

    /// Return the registration carrying `id`.
    ///
    /// # Errors
    ///
    /// Returns [`UnitCodeUnknown::Identity`] when no registration carries `id`.
    pub fn entry(&self, id: UnitCodeId) -> Result<&UnitCodeEntry, UnitCodeUnknown> {
        self.by_id
            .get(&id)
            .and_then(|position| self.entries.get(*position))
            .ok_or(UnitCodeUnknown::Identity)
    }

    /// Return the identity assigned to `token`.
    ///
    /// # Errors
    ///
    /// Returns [`UnitCodeUnknown::Token`] when the token was never registered.
    pub fn id_of_token(&self, token: UnitCodeToken) -> Result<UnitCodeId, UnitCodeUnknown> {
        self.by_token
            .get(&token)
            .and_then(|position| self.entries.get(*position))
            .map(UnitCodeEntry::id)
            .ok_or(UnitCodeUnknown::Token)
    }

    /// Return the identity assigned to `code`.
    ///
    /// # Errors
    ///
    /// Returns [`UnitCodeUnknown::Token`] when the linked Recommendation 20
    /// artifact defines a code the committed snapshot has not registered, which
    /// is what an unregenerated snapshot looks like.
    pub fn id_of(&self, code: UnitCode) -> Result<UnitCodeId, UnitCodeUnknown> {
        let token = UnitCodeToken::try_from(code.as_str()).map_err(|_| UnitCodeUnknown::Token)?;
        self.id_of_token(token)
    }

    /// Return the typed code carrying `id`.
    ///
    /// # Errors
    ///
    /// Returns [`UnitCodeUnknown::Identity`] when no registration carries `id`,
    /// and [`UnitCodeUnknown::WithdrawnCode`] when the registration names a
    /// token the linked artifact no longer defines. A caller that must render a
    /// withdrawn code rather than interpret it reads
    /// [`UnitCodeEntry::token`] from [`UnitCodeRegistry::entry`] instead.
    pub fn unit_code_of(&self, id: UnitCodeId) -> Result<UnitCode, UnitCodeUnknown> {
        self.entry(id)?.unit_code().ok_or(UnitCodeUnknown::WithdrawnCode)
    }
}

/// Read one registration from a snapshot line.
///
/// The line borrows from the compiled-in snapshot, and every field borrows from
/// the line, which is what lets a token be held without copying it.
fn parse_entry(line: &'static str, number: usize) -> Result<UnitCodeEntry, UnitCodeSnapshotMalformed> {
    let fields: Vec<&'static str> = line.split(FIELD_SEPARATOR).collect();
    let [identity, token, first, retired] = fields.as_slice() else {
        return Err(UnitCodeSnapshotMalformed::FieldCount {
            line: number,
            expected: FIELD_COUNT,
        });
    };
    let identity = identity
        .parse::<i16>()
        .map_err(|_| UnitCodeSnapshotMalformed::Identity { line: number })
        .and_then(|stored| UnitCodeId::try_from(stored).map_err(|_| UnitCodeSnapshotMalformed::Identity { line: number }))?;
    let token = UnitCodeToken::try_from(*token).map_err(|_| UnitCodeSnapshotMalformed::Token { line: number })?;
    let first_revision = parse_revision(first, number)?;
    let retired_revision = if retired.is_empty() { None } else { Some(parse_revision(retired, number)?) };
    Ok(UnitCodeEntry::new(identity, token, first_revision, retired_revision))
}

/// Read a revision number from a snapshot field.
fn parse_revision(field: &str, line: usize) -> Result<Rec20Revision, UnitCodeSnapshotMalformed> {
    field
        .parse::<i16>()
        .map_err(|_| UnitCodeSnapshotMalformed::Revision { line })
        .and_then(|number| Rec20Revision::try_from(number).map_err(|_| UnitCodeSnapshotMalformed::Revision { line }))
}

/// The committed identity snapshot could not be read.
#[derive(Clone, Copy, Debug, Eq, Error, PartialEq)]
pub enum UnitCodeSnapshotMalformed {
    /// A registration did not carry the expected number of fields.
    #[error("line {line} of the unit-code snapshot does not carry {expected} fields")]
    FieldCount {
        /// One-based line number.
        line: usize,
        /// Number of fields a registration carries.
        expected: usize,
    },
    /// A registration's identity did not parse.
    #[error("line {line} of the unit-code snapshot does not carry a usable identity")]
    Identity {
        /// One-based line number.
        line: usize,
    },
    /// A registration's token did not parse.
    #[error("line {line} of the unit-code snapshot does not carry a usable common code")]
    Token {
        /// One-based line number.
        line: usize,
    },
    /// A registration's revision did not parse.
    #[error("line {line} of the unit-code snapshot does not carry a usable revision")]
    Revision {
        /// One-based line number.
        line: usize,
    },
    /// Two registrations claimed the same identity.
    #[error("line {line} of the unit-code snapshot repeats an identity already assigned")]
    RepeatedIdentity {
        /// One-based line number.
        line: usize,
    },
    /// Two registrations claimed the same token.
    #[error("line {line} of the unit-code snapshot repeats a common code already registered")]
    RepeatedToken {
        /// One-based line number.
        line: usize,
    },
}

/// A lookup named something the catalog does not hold.
#[derive(Clone, Copy, Debug, Eq, Error, PartialEq)]
pub enum UnitCodeUnknown {
    /// No registration carries the identity.
    #[error("the unit-code catalog holds no code under that identity")]
    Identity,
    /// No registration carries the common code.
    #[error("the unit-code catalog holds no identity for that common code")]
    Token,
    /// The registration names a code the linked artifact no longer defines.
    #[error("the identity names a common code the linked Recommendation 20 revision has withdrawn")]
    WithdrawnCode,
}

#[cfg(test)]
mod tests {
    use crate::{
        unit_code_id::UnitCodeId,
        unit_code_registry::{UnitCodeRegistry, UnitCodeSnapshotMalformed, UnitCodeUnknown, registry},
        unit_code_token::UnitCodeToken,
    };

    /// A two-registration snapshot in the committed format.
    const SAMPLE: &str = "# generated - never hand-edited\n1\tKGM\t17\t\n2\tMTR\t17\t\n";

    #[test]
    fn a_snapshot_registration_decodes_to_its_typed_code() {
        let decoded = UnitCodeRegistry::parse(SAMPLE)
            .ok()
            .and_then(|catalog| UnitCodeId::try_from(2_i16).ok().and_then(|id| catalog.unit_code_of(id).ok()));
        assert_eq!(decoded.map(|code| code.as_str()), Some("MTR"));
    }

    #[test]
    fn a_common_code_encodes_to_the_identity_the_snapshot_assigned() {
        let encoded = UnitCodeRegistry::parse(SAMPLE)
            .ok()
            .and_then(|catalog| UnitCodeToken::try_from("KGM").ok().and_then(|token| catalog.id_of_token(token).ok()));
        assert_eq!(encoded.map(UnitCodeId::get), Some(1));
    }

    #[test]
    fn an_unregistered_identity_fails_the_decode() {
        let decoded = UnitCodeRegistry::parse(SAMPLE)
            .ok()
            .and_then(|catalog| UnitCodeId::try_from(9_999_i16).ok().map(|id| catalog.unit_code_of(id)));
        assert_eq!(decoded, Some(Err(UnitCodeUnknown::Identity)));
    }

    #[test]
    fn an_unregistered_common_code_fails_the_encode() {
        let encoded = UnitCodeRegistry::parse(SAMPLE)
            .ok()
            .and_then(|catalog| UnitCodeToken::try_from("SEC").ok().map(|token| catalog.id_of_token(token)));
        assert_eq!(encoded, Some(Err(UnitCodeUnknown::Token)));
    }

    #[test]
    fn a_registration_whose_code_the_linked_revision_dropped_reports_the_withdrawal() {
        let catalog = UnitCodeRegistry::parse("1\tQ99\t9\t17");
        let decoded = catalog
            .ok()
            .and_then(|catalog| UnitCodeId::try_from(1_i16).ok().map(|id| catalog.unit_code_of(id)));
        assert_eq!(decoded, Some(Err(UnitCodeUnknown::WithdrawnCode)));
    }

    #[test]
    fn a_registration_carrying_the_wrong_number_of_fields_is_refused() {
        assert_eq!(
            UnitCodeRegistry::parse("1\tQ99\t9\t17\t"),
            Err(UnitCodeSnapshotMalformed::FieldCount { line: 1, expected: 4 })
        );
    }

    #[test]
    fn a_repeated_identity_is_refused() {
        assert_eq!(
            UnitCodeRegistry::parse("1\tKGM\t17\t\n1\tMTR\t17\t"),
            Err(UnitCodeSnapshotMalformed::RepeatedIdentity { line: 2 })
        );
    }

    #[test]
    fn a_repeated_common_code_is_refused() {
        assert_eq!(
            UnitCodeRegistry::parse("1\tKGM\t17\t\n2\tKGM\t17\t"),
            Err(UnitCodeSnapshotMalformed::RepeatedToken { line: 2 })
        );
    }

    #[test]
    fn a_non_positive_identity_is_refused() {
        assert_eq!(UnitCodeRegistry::parse("0\tKGM\t17\t"), Err(UnitCodeSnapshotMalformed::Identity { line: 1 }));
    }

    #[test]
    fn a_malformed_common_code_is_refused() {
        assert_eq!(UnitCodeRegistry::parse("1\tkgm\t17\t"), Err(UnitCodeSnapshotMalformed::Token { line: 1 }));
    }

    #[test]
    fn a_malformed_revision_is_refused() {
        assert_eq!(
            UnitCodeRegistry::parse("1\tKGM\tseventeen\t"),
            Err(UnitCodeSnapshotMalformed::Revision { line: 1 })
        );
    }

    #[test]
    fn the_committed_snapshot_parses() {
        assert!(registry().is_ok());
    }
}
